scripts.script:
if not game:IsLoaded() then task.wait() end;

local old; old = hookmetamethod(game:GetService("ReplicatedStorage"), "__namecall", function(self, ...)
    local method = getnamecallmethod()
    local args = {...}

    if (method == "FireServer" or method == "InvokeServer") and args[1] == "ReportViolation" then
        return
    end

    return old(self, ...)
end)
